import { test } from 'node:test';
import * as assert from 'node:assert/strict';
import * as capCell from '../lib/socket-territory-observer.js';

/**
 * union-acceptance/linux-socket-territory-observation-capcell-fabrication.test.mjs
 * 
 * Verifies the capability cell for Linux socket territory observation.
 * Adheres to constraints: no floats, no pricing, no socket mutation, 
 * typed refusals, and rational share representation.
 */

test('exact-loopback-tcp-territory', () => {
    // Given: an injected Linux socket snapshot and an explicit admissibility policy
    const mockSnapshot = {
        namespace: 'netns:default',
        family: 'AF_INET',
        protocol: 'TCP',
        listeners: [
            { addr: '127.0.0.1', port: 8080 },
            { addr: '127.0.0.1', port: 8081 }
        ]
    };

    const admissibility = {
        denominator: '4', // 4 total berths admissible
        permittedPorts: [8080, 8081, 8082, 8083]
    };

    // When: the territory is observed
    const observation = capCell.observeLinuxSocketTerritory(mockSnapshot, admissibility);

    // Then: capacity and occupancy sets are derived
    assert.strictEqual(observation.capacity.numerator, '4');
    assert.strictEqual(observation.capacity.denominator, '1');
    assert.strictEqual(observation.occupancy.numerator, '2');
    assert.strictEqual(observation.occupancy.denominator, '1');

    // Then: occupied/admissible and available/admissible are reduced exact fractions
    // Occupied: 2/4 -> 1/2
    assert.strictEqual(observation.ratios.occupiedAdmissible.numerator, '1');
    assert.strictEqual(observation.ratios.occupiedAdmissible.denominator, '2');

    // Available: 2/4 -> 1/2
    assert.strictEqual(observation.ratios.availableAdmissible.numerator, '1');
    assert.strictEqual(observation.ratios.availableAdmissible.denominator, '2');

    // Then: each admissible berth has exact share 1/N
    // Here N = 4, so share is 1/4
    assert.strictEqual(observation.sharePerBerth.numerator, '1');
    assert.strictEqual(observation.sharePerBerth.denominator, '4');
});

test('typed-observation-refusal', () => {
    // Given: a namespace state that cannot be observed
    const invalidSnapshot = { namespace: null, error: 'EPERM' };
    const admissibility = { denominator: '1', permittedPorts: [] };

    // When: the operation is invoked
    const result = capCell.observeLinuxSocketTerritory(invalidSnapshot, admissibility);

    // Then: a typed refusal identifies the missing observation
    assert.strictEqual(result.status, 'REFUSAL');
    assert.strictEqual(result.code, 'EPERM');

    // Then: no zero measurement is fabricated
    assert.strictEqual(result.capacity, undefined);
    assert.strictEqual(result.occupancy, undefined);
});

/**
 * Forbidden Clause Verification
 */
test('forbidden-patterns-absent', () => {
    const observation = capCell.observeLinuxSocketTerritory({}, { denominator: '1' });

    // Assert no pricing claims
    assert.strictEqual(observation.price, undefined, 'Price claim forbidden');

    // Assert no float values
    const checkNoFloats = (obj) => {
        for (const key in obj) {
            if (typeof obj[key] === 'string' && obj[key].includes('.')) {
                throw new Error(`Float detected in ${key}: ${obj[key]}`);
            }
        }
    };
    checkNoFloats(observation.ratios || {});
});
